from typing import List

class Solution:
    def partitionDisjoint(self, nums: List[int]) -> int:
        max_left = nums[0]
        cur_max = nums[0]
        split = 0
        for i in range(1, len(nums)):
            cur_max = max(cur_max, nums[i])
            if nums[i] < max_left:
                split = i
                max_left = cur_max
        return split + 1

